public final class Period {
    private final Date start, end;

    public Period(Date start, Date end) {
        // 1. Defensively copy FIRST:
        this.start = new Date(start.getTime());
        this.end = new Date(end.getTime());

        // 2. Validate the COPIES, not the parameters:
        if (this.start.compareTo(this.end) > 0) {
            throw new IllegalArgumentException(this.start + " after " + this.end);
        }
    }
}

BigDecimal a = new BigDecimal("2.0");
BigDecimal b = new BigDecimal("2.00");

Set<BigDecimal> hashSet = new HashSet<>();
hashSet.add(a); hashSet.add(b);
System.out.println(hashSet.size()); // 2! (uses equals)

Set<BigDecimal> treeSet = new TreeSet<>();
treeSet.add(a); treeSet.add(b);
System.out.println(treeSet.size()); // 1! (uses compareTo)

Integer a = 100, b = 100;
System.out.println(a == b); // true (same cached instance)

Integer c = 1000, d = 1000;
System.out.println(c == d); // false (different heap objects!)
System.out.println(c.equals(d)); // true (ALWAYS use .equals for wrappers!)

public record Team(String name, List<String> members) {
    // Defensively copy to enforce deep immutability:
    public Team {
        members = List.copyOf(members); // Unmodifiable defensive copy!
    }
}

String s1 = "mastery";
String s2 = "mastery";
String s3 = new String("mastery");

System.out.println(s1 == s2); // true (same pooled reference)
System.out.println(s1 == s3); // false (s3 is an explicit new heap object!)
System.out.println(s1.equals(s3)); // true (content equality)

